import React, { useState, useEffect } from 'react';
import TaskComments from './TaskComments';
import TaskAttachments from './TaskAttachments';

const TaskDetailsModal = ({ task, isOpen, onClose, onTaskUpdate, currentUser }) => {
  const [editedTask, setEditedTask] = useState(task);
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    setEditedTask(task);
  }, [task]);

  if (!isOpen) return null;

  const handleSave = async () => {
    try {
      await onTaskUpdate(task.id, editedTask);
      setIsEditing(false);
    } catch (error) {
      console.error('Error updating task:', error);
    }
  };

  const handleStatusChange = async (newStatus) => {
    await onTaskUpdate(task.id, { status: newStatus });
  };

  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'high': return '#e74c3c';
      case 'medium': return '#f39c12';
      case 'low': return '#27ae60';
      default: return '#95a5a6';
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Not set';
    return new Date(dateString).toLocaleDateString();
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>Task Details</h2>
          <button className="close-button" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          {/* Task Information */}
          <div className="task-details-section">
            <div className="task-header">
              {isEditing ? (
                <input
                  type="text"
                  value={editedTask.title}
                  onChange={(e) => setEditedTask({...editedTask, title: e.target.value})}
                  className="task-title-input"
                />
              ) : (
                <h3>{task.title}</h3>
              )}
              
              <div className="task-actions-top">
                <select 
                  value={task.status} 
                  onChange={(e) => handleStatusChange(e.target.value)}
                  className="status-select"
                >
                  <option value="todo">To Do</option>
                  <option value="in_progress">In Progress</option>
                  <option value="done">Done</option>
                </select>
                
                <button 
                  className="btn btn-outline"
                  onClick={() => setIsEditing(!isEditing)}
                >
                  {isEditing ? 'Cancel' : 'Edit'}
                </button>
              </div>
            </div>

            <div className="task-meta-grid">
              <div className="meta-item">
                <strong>Priority:</strong>
                <span 
                  className="priority-badge"
                  style={{ backgroundColor: getPriorityColor(task.priority) }}
                >
                  {task.priority || 'Not set'}
                </span>
              </div>
              
              <div className="meta-item">
                <strong>Due Date:</strong>
                <span>{formatDate(task.due_date)}</span>
              </div>
              
              <div className="meta-item">
                <strong>Assignee:</strong>
                <span>{task.assignee_name || 'Unassigned'}</span>
              </div>
              
              <div className="meta-item">
                <strong>Created by:</strong>
                <span>{task.created_by_name}</span>
              </div>
            </div>

            <div className="task-description-section">
              <strong>Description:</strong>
              {isEditing ? (
                <textarea
                  value={editedTask.description || ''}
                  onChange={(e) => setEditedTask({...editedTask, description: e.target.value})}
                  className="task-description-input"
                  rows="4"
                  placeholder="Add a description..."
                />
              ) : (
                <p className="task-description">
                  {task.description || 'No description provided.'}
                </p>
              )}
            </div>

            {isEditing && (
              <div className="edit-actions">
                <button className="btn btn-primary" onClick={handleSave}>
                  Save Changes
                </button>
              </div>
            )}
          </div>

          {/* Comments Section */}
          <div className="comments-section">
            <TaskComments 
              taskId={task.id} 
              currentUser={currentUser}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default TaskDetailsModal;
